} Vec;

static void vec_push(Vec *v, Edge e) {
    if (v->sz == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->a = (Edge*)realloc(v->a, sizeof(Edge) * v->cap);
    }
    v->a[v->sz++] = e;
}

static void add_edge(Vec *g, int u, int v, int cap) {
    Edge a = {v, cap, g[v].sz};
    Edge b = {u, 0,   g[u].sz};
    vec_push(&g[u], a);
    vec_push(&g[v], b);
}

static int min_int(int a, int b) { return a < b ? a : b; }

typedef struct Queue {
    int *a;
    int head, tail;
} Queue;

static void qinit(Queue *q, int n) {
    q->a = (int*)malloc(sizeof(int) * n);
    q->head = q->tail = 0;
}
static void qfree(Queue *q) { free(q->a); }
static void qpush(Queue *q, int x) { q->a[q->tail++] = x; }
static int qpop(Queue *q) { return q->a[q->head++]; }
static int qempty(Queue *q) { return q->head == q->tail; }

static int bfs(Vec *g, int N, int s, int t, int *level) {
    for (int i = 0; i < N; i++) level[i] = -1;
    Queue q;
    qinit(&q, N);
    level[s] = 0;
    qpush(&q, s);
    while (!qempty(&q)) {
        int v = qpop(&q);
        for (int i = 0; i < g[v].sz; i++) {
            Edge *e = &g[v].a[i];
            if (e->cap > 0 && level[e->to] < 0) {
                level[e->to] = level[v] + 1;
                qpush(&q, e->to);
            }
        }
    }
    int ok = (level[t] >= 0);
    qfree(&q);
    return ok;
}

static int dfs(Vec *g, int v, int t, int f, int *level, int *it) {
    if (v == t) return f;
    for (int *i = &it[v]; *i < g[v].sz; (*i)++) {
        Edge *e = &g[v].a[*i];
        if (e->cap <= 0 || level[v] >= level[e->to]) continue;
        int d = dfs(g, e->to, t, min_int(f, e->cap), level, it);
        if (d > 0) {
            e->cap -= d;
            g[e->to].a[e->rev].cap += d;
            return d;
        }
    }
    return 0;
}

static int dinic(Vec *g, int N, int s, int t) {
    int flow = 0;
    int *level = (int*)malloc(sizeof(int) * N);
    int *it = (int*)malloc(sizeof(int) * N);
    while (bfs(g, N, s, t, level)) {
        for (int i = 0; i < N; i++) it[i] = 0;
        while (1) {
            int f = dfs(g, s, t, 1e9, level, it);
            if (!f) break;
            flow += f;
            if (flow >= 1000000000) break;
        }
        if (flow >= 1000000000) break;
    }
    free(level);
    free(it);
    return flow;
}

