            for (int j = 0; j < W; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] != '.') {
                    int idx = i * W + j;
                    leafNodes.add(idx);
                    if (grid[i][j] == 'S') S = idx;
                    if (grid[i][j] == 'T') T = idx;
                }
            }
        }

        if (S == -1 || T == -1) {
            System.out.println(-1);
            return;
        }

        // Split nodes: in -> out with capacity 1 (except S and T have infinite capacity)
        for (int idx : leafNodes) {
            int in = idx;
            int out = idx + nodeCount;
            if (idx == S || idx == T) {
                addEdge(in, out, Integer.MAX_VALUE);
            } else {
                addEdge(in, out, 1);
            }
        }

        // Connect rows and columns: same row or same column -> infinite capacity edges
        for (int i = 0; i < H; i++) {
            List<Integer> rowLeaves = new ArrayList<>();
            for (int j = 0; j < W; j++) {
                if (grid[i][j] != '.') rowLeaves.add(i * W + j);
            }
            for (int a = 0; a < rowLeaves.size(); a++) {
                for (int b = a + 1; b < rowLeaves.size(); b++) {
                    int u = rowLeaves.get(a);
                    int v = rowLeaves.get(b);
                    // connect out(u) -> in(v) and out(v) -> in(u)
                    addEdge(u + nodeCount, v, Integer.MAX_VALUE);
                    addEdge(v + nodeCount, u, Integer.MAX_VALUE);
                }
            }
        }

        for (int j = 0; j < W; j++) {
            List<Integer> colLeaves = new ArrayList<>();
            for (int i = 0; i < H; i++) {
                if (grid[i][j] != '.') colLeaves.add(i * W + j);
            }
            for (int a = 0; a < colLeaves.size(); a++) {
                for (int b = a + 1; b < colLeaves.size(); b++) {
                    int u = colLeaves.get(a);
                    int v = colLeaves.get(b);
                    addEdge(u + nodeCount, v, Integer.MAX_VALUE);
                    addEdge(v + nodeCount, u, Integer.MAX_VALUE);
                }
            }
        }

        level = new int[totalNodes];
        iter = new int[totalNodes];

        int sourceOut = S + nodeCount;
        int sinkIn = T;
        int result = maxFlow(sourceOut, sinkIn);

        if (result >= Integer.MAX_VALUE / 2) {
            System.out.println(-1);
        } else {
            System.out.println(result);
        }
    }
}

import java.util.*;

public class Main {
    static int[] head, nxt, to, cap;
    static int cnt, n;

    static void init(int nodes, int edges) {
        n = nodes;
        head = new int[nodes]; Arrays.fill(head, -1);
        nxt = new int[edges * 2]; to = new int[edges * 2]; cap = new int[edges * 2];
        cnt = 0;
    }

    static void addEdge(int u, int v, int c) {
        to[cnt] = v; cap[cnt] = c; nxt[cnt] = head[u]; head[u] = cnt++;
        to[cnt] = u; cap[cnt] = 0; nxt[cnt] = head[v]; head[v] = cnt++;
    }

    static int[] level, iter;

    static boolean bfs(int s, int t) {
        level = new int[n]; Arrays.fill(level, -1);
        Queue<Integer> q = new LinkedList<>();
        level[s] = 0; q.add(s);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (int e = head[v]; e != -1; e = nxt[e])
                if (cap[e] > 0 && level[to[e]] < 0) { level[to[e]] = level[v] + 1; q.add(to[e]); }
        }
        return level[t] >= 0;
    }

    static int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (; iter[v] != -1; iter[v] = nxt[iter[v]]) {
            int e = iter[v];
            if (cap[e] > 0 && level[to[e]] == level[v] + 1) {
                int d = dfs(to[e], t, Math.min(f, cap[e]));
                if (d > 0) { cap[e] -= d; cap[e^1] += d; return d; }
            }
        }
        return 0;
    }

    static int maxflow(int s, int t) {
        int flow = 0;
        while (bfs(s, t)) { iter = Arrays.copyOf(head, n); int d; while ((d = dfs(s, t, Integer.MAX_VALUE)) > 0) flow += d; }
        return flow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt(), W = sc.nextInt();
        char[][] grid = new char[H][W];
        int sId = -1, tId = -1;
        List<int[]> leaves = new ArrayList<>();
        for (int i = 0; i < H; i++) { String row = sc.next(); for (int j = 0; j < W; j++) { grid[i][j] = row.charAt(j); if (grid[i][j] != '.' ) { if (grid[i][j] == 'S') sId = leaves.size(); else if (grid[i][j] == 'T') tId = leaves.size(); leaves.add(new int[]{i, j}); } } }
        int N = leaves.size();
        // Check direct connection
        int[] sp = leaves.get(sId), tp = leaves.get(tId);
        if (sp[0] == tp[0] || sp[1] == tp[1]) { System.out.println(-1); return; }
        // Node split: node i -> i_in = i, i_out = i+N
        init(2 * N, N * N * 4 + N);
        for (int i = 0; i < N; i++) { int c = (i == sId || i == tId) ? Integer.MAX_VALUE / 2 : 1; addEdge(i, i + N, c); }
        for (int i = 0; i < N; i++) for (int j = i + 1; j < N; j++) { int[] a = leaves.get(i), b = leaves.get(j); if (a[0] == b[0] || a[1] == b[1]) { addEdge(i + N, j, Integer.MAX_VALUE / 2); addEdge(j + N, i, Integer.MAX_VALUE / 2); } }
        System.out.println(maxflow(sId + N, tId));
    }
}

import java.io.*;
import java.util.*;

/*
We model each row and each column as a vertex in a bipartite graph.
Each lotus leaf at (r, c) is an edge between row-node r and column-node c.

A frog standing on a leaf can jump to any other leaf in the same row or column,
which means movement between leaves corresponds to traversing this bipartite graph.
So disconnecting S from T by removing leaves is exactly removing edges to separate
the edge of S from the edge of T.

More precisely:
- Let S be at (rs, cs), T at (rt, ct).
- Starting from S, the frog can access row rs and column cs.
- Reaching T means being able to access row rt or column ct and then land on T.
Thus we need a minimum edge cut between the source side {rs, cs} and target side {rt, ct}.

Standard reduction:
- Split each leaf-edge into a node with capacity 1 (to count removing that leaf).
- Infinite-capacity connections from its row to leaf-in, leaf-out to its column.
- Super source connects to rs and cs with INF.
- rt and ct connect to super sink with INF.
- Leaves S and T cannot be removed, so give them INF instead of 1.

Answer is min-cut / max-flow; if >= INF/2, output -1.

Constraints are not shown, so use Dinic with adjacency lists and coordinate compression
only over rows/cols that appear? Since H,W may be large but grid input likely explicit.
We read H lines, so use all rows and columns directly.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Edge {
        int to, rev;
        long cap;

        Edge(int to, int rev, long cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static class Dinic {
        List<Edge>[] g;
        int[] level, it;

        @SuppressWarnings("unchecked")
        Dinic(int n) {
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            level = new int[n];
            it = new int[n];
        }

        void addEdge(int fr, int to, long cap) {
            Edge fwd = new Edge(to, g[to].size(), cap);
            Edge rev = new Edge(fr, g[fr].size(), 0);
            g[fr].add(fwd);
            g[to].add(rev);
        }

        boolean bfs(int s, int t) {
            Arrays.fill(level, -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : g[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        long dfs(int v, int t, long f) {
            if (v == t) return f;
            for (; it[v] < g[v].size(); it[v]++) {
                Edge e = g[v].get(it[v]);
                if (e.cap > 0 && level[v] < level[e.to]) {
                    long d = dfs(e.to, t, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        g[e.to].get(e.rev).cap += d;
                        return d;
                    }
                }
            }
            return 0;
        }

        long maxFlow(int s, int t) {
            long flow = 0;
            long INF = Long.MAX_VALUE / 4;
            while (bfs(s, t)) {
                Arrays.fill(it, 0);
                long f;
                while ((f = dfs(s, t, INF)) > 0) flow += f;
            }
            return flow;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String hs = fs.next();
        if (hs == null) return;
        int H = Integer.parseInt(hs);
        int W = fs.nextInt();

        char[][] grid = new char[H][];
        int sr = -1, sc = -1, tr = -1, tc = -1;
        List<int[]> leaves = new ArrayList<>();

        for (int i = 0; i < H; i++) {
            String s = fs.next();
            grid[i] = s.toCharArray();
            for (int j = 0; j < W; j++) {
                char ch = grid[i][j];
                if (ch != '.') {
                    leaves.add(new int[]{i, j, ch});
                    if (ch == 'S') {
                        sr = i;
                        sc = j;
                    } else if (ch == 'T') {
                        tr = i;
                        tc = j;
                    }
                }
            }
        }

        // If S and T are in same row or same column, impossible:
        // since S and T themselves cannot be removed, frog can jump directly.
        if (sr == tr || sc == tc) {
            System.out.println(-1);
            return;
        }

        int nLeaves = leaves.size();

        int rowBase = 0;               // H nodes
        int colBase = rowBase + H;     // W nodes
        int inBase = colBase + W;      // nLeaves nodes
        int outBase = inBase + nLeaves;// nLeaves nodes
        int SRC = outBase + nLeaves;
        int SNK = SRC + 1;
        int N = SNK + 1;

        Dinic dinic = new Dinic(N);
        long INF = 1_000_000_000_000L;

        for (int idx = 0; idx < nLeaves; idx++) {
            int r = leaves.get(idx)[0];
            int c = leaves.get(idx)[1];
            char ch = (char) leaves.get(idx)[2];

            int in = inBase + idx;
            int out = outBase + idx;
            long cap = (ch == 'S' || ch == 'T') ? INF : 1;

            dinic.addEdge(in, out, cap);

            int rowNode = rowBase + r;
            int colNode = colBase + c;

            dinic.addEdge(rowNode, in, INF);
            dinic.addEdge(colNode, in, INF);
            dinic.addEdge(out, rowNode, INF);
            dinic.addEdge(out, colNode, INF);
        }

        dinic.addEdge(SRC, rowBase + sr, INF);
        dinic.addEdge(SRC, colBase + sc, INF);
        dinic.addEdge(rowBase + tr, SNK, INF);
        dinic.addEdge(colBase + tc, SNK, INF);

        long ans = dinic.maxFlow(SRC, SNK);
        if (ans >= INF / 2) System.out.println(-1);
        else System.out.println(ans);
    }
}

import sys
from collections import deque

input = sys.stdin.readline

H, W = map(int, input().split())
grid = [list(input().strip()) for _ in range(H)]

rows = [set() for _ in range(H)]
cols = [set() for _ in range(W)]

S = None
T = None
leaf_id = 0
leaf_positions = {}

# Assign ids to leaves
for i in range(H):
    for j in range(W):
        if grid[i][j] != '.':
            leaf_id += 1
            leaf_positions[(i, j)] = leaf_id
            rows[i].add(leaf_id)
            cols[j].add(leaf_id)
            if grid[i][j] == 'S':
                S = leaf_id
            elif grid[i][j] == 'T':
                T = leaf_id

# Build flow network
# Nodes: source = 0, sink = 1
# Each leaf has two nodes: in (2*id) and out (2*id+1)
# Each row and column also represented as nodes
# But simpler: We can directly connect leaves in same row/col with infinite capacity edges.
# However, we need min nodes to delete, so we split each leaf node into in/out with capacity 1 (except S,T have INF).

INF = 10**9
N = 2 * leaf_id + 2
src = 0
sink = 1
cap = [[0] * N for _ in range(N)]
adj = [[] for _ in range(N)]

def add_edge(u, v, c):
    cap[u][v] = c
    adj[u].append(v)
    adj[v].append(u)

# Split each leaf
for (i,j), lid in leaf_positions.items():
    in_node = 2 * lid
    out_node = 2 * lid + 1
    if lid == S or lid == T:
        add_edge(in_node, out_node, INF)
    else:
        add_edge(in_node, out_node, 1)

# Connect leaves in same row
for i in range(H):
    leaves = list(rows[i])
    for a in leaves:
        for b in leaves:
            if a < b:
                u = 2 * a + 1  # out of a
                v = 2 * b      # in of b
                add_edge(u, v, INF)
                add_edge(v, u, INF)

# Connect leaves in same column
for j in range(W):
    leaves = list(cols[j])
    for a in leaves:
        for b in leaves:
            if a < b:
                u = 2 * a + 1
                v = 2 * b
                add_edge(u, v, INF)
                add_edge(v, u, INF)

# Source to S-in, T-out to sink
add_edge(src, 2 * S, INF)
add_edge(2 * T + 1, sink, INF)

# Dinic max flow
level = [0] * N
it = [0] * N

def bfs():
    for i in range(N):
        level[i] = -1
    q = deque([src])
    level[src] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if level[v] < 0 and cap[u][v] > 0:
                level[v] = level[u] + 1
                q.append(v)
    return level[sink] >= 0

def dfs(u, f):
    if u == sink:
        return f
    for i in range(it[u], len(adj[u])):
        v = adj[u][i]
        if level[v] == level[u] + 1 and cap[u][v] > 0:
            ret = dfs(v, min(f, cap[u][v]))
            if ret > 0:
                cap[u][v] -= ret
                cap[v][u] += ret
                return ret
        it[u] += 1
    return 0

flow = 0
while bfs():
    it = [0] * N
    while True:
        f = dfs(src, INF)
        if f == 0:
            break
        flow += f

if flow >= INF:
    print(-1)
else:
